17	// The Flutter tool hits file system and process errors that only the end-user can address.
18	// We would like these errors to not hit crash logging. In these cases, we
19	// should exit gracefully and provide potentially useful advice. For example, if
20	// a write fails because the target device is full, we can explain that with a
21	// ToolExit and a message that is more clear than the FileSystemException by
22	// itself.
23	
24	/// On windows this is error code 2: ERROR_FILE_NOT_FOUND, and on
25	/// macOS/Linux it is error code 2/ENOENT: No such file or directory.
26	const int kSystemCannotFindFile = 2;
27	
28	/// A [FileSystem] that throws a [ToolExit] on certain errors.
29	///
30	/// If a [FileSystem] error is not caused by the Flutter tool, and can only be
31	/// addressed by the user, it should be caught by this [FileSystem] and thrown
32	/// as a [ToolExit] using [throwToolExit].
33	///
34	/// Cf. If there is some hope that the tool can continue when an operation fails
35	/// with an error, then that error/operation should not be handled here. For
36	/// example, the tool should generally be able to continue executing even if it
37	/// fails to delete a file.
38	class ErrorHandlingFileSystem extends ForwardingFileSystem {
39	  ErrorHandlingFileSystem({
40	    required FileSystem delegate,
41	    required Platform platform,
42	  }) :
43	      _platform = platform,
44	      super(delegate);
45	
46	  @visibleForTesting
47	  FileSystem get fileSystem => delegate;
48	
49	  final Platform _platform;
50	
51	  /// Allow any file system operations executed within the closure to fail with any
52	  /// operating system error, rethrowing an [Exception] instead of a [ToolExit].
53	  ///
54	  /// This should not be used with async file system operation.
55	  ///
56	  /// This can be used to bypass the [ErrorHandlingFileSystem] permission exit
57	  /// checks for situations where failure is acceptable, such as the flutter
58	  /// persistent settings cache.
59	  static void noExitOnFailure(void Function() operation) {
60	    final bool previousValue = ErrorHandlingFileSystem._noExitOnFailure;
61	    try {
62	      ErrorHandlingFileSystem._noExitOnFailure = true;
63	      operation();
64	    } finally {
65	      ErrorHandlingFileSystem._noExitOnFailure = previousValue;
66	    }
67	  }
68	
69	  /// Delete the file or directory and return true if it exists, take no
70	  /// action and return false if it does not.
71	  ///
72	  /// This method should be preferred to checking if it exists and
73	  /// then deleting, because it handles the edge case where the file or directory
74	  /// is deleted by a different program between the two calls.
75	  static bool deleteIfExists(FileSystemEntity file, {bool recursive = false}) {
76	    if (!file.existsSync()) {
77	      return false;
78	    }
79	    try {
80	      file.deleteSync(recursive: recursive);
81	    } on FileSystemException catch (err) {
82	      // Certain error codes indicate the file could not be found. It could have
83	      // been deleted by a different program while the tool was running.
84	      // if it still exists, the file likely exists on a read-only volume.
85	      if (err.osError?.errorCode != kSystemCannotFindFile || _noExitOnFailure) {
86	        rethrow;
87	      }
88	      if (file.existsSync()) {
89	        throwToolExit(
90	          'The Flutter tool tried to delete the file or directory ${file.path} but was '
91	          "unable to. This may be due to the file and/or project's location on a read-only "
92	          'volume. Consider relocating the project and trying again',
93	        );
94	      }
95	    }
96	    return true;
97	  }
