99	  static bool _noExitOnFailure = false;
100	
101	  @override
102	  Directory get currentDirectory {
103	    try {
104	      return _runSync(() =>  directory(delegate.currentDirectory), platform: _platform);
105	    } on FileSystemException catch (err) {
106	      // Special handling for OS error 2 for current directory only.
107	      if (err.osError?.errorCode == kSystemCannotFindFile) {
108	        throwToolExit(
109	          'Unable to read current working directory. This can happen if the directory the '
110	          'Flutter tool was run from was moved or deleted.'
111	        );
112	      }
113	      rethrow;
114	    }
115	  }
116	
