118	  File file(dynamic path) => ErrorHandlingFile(
119	    platform: _platform,
120	    fileSystem: this,
121	    delegate: delegate.file(path),
122	  );
123	
124	  @override
125	  Directory directory(dynamic path) => ErrorHandlingDirectory(
126	    platform: _platform,
127	    fileSystem: this,
128	    delegate: delegate.directory(path),
129	  );
