138	  // Caching the path context here and clearing when the currentDirectory setter
139	  // is updated works since the flutter tool restricts usage of dart:io directly
140	  // via the forbidden import tests. Otherwise, the path context's current
141	  // working directory might get out of sync, leading to unexpected results from
142	  // methods like `path.relative`.
143	  @override
144	  p.Context get path => _cachedPath ??= delegate.path;
145	  p.Context? _cachedPath;
146	
147	  @override
148	  set currentDirectory(dynamic path) {
149	    _cachedPath = null;
150	    delegate.currentDirectory = path;
151	  }
152	
153	  @override
154	  String toString() => delegate.toString();
155	}
